    exerciseTime: Optional[BusinessCenterTime] = Field(default=None, description="""Specifies the time at which an option contained within the financial product woulld be exercised. The time may be omitted if the contractual product allows for only a single time of exercise (European exercise).""", json_schema_extra = { "linkml_meta": {'domain_of': ['ExerciseInstruction']} })
