class InformationSource(ConfiguredBaseModel):
    """
    A class defining the source for a piece of information (e.g. a rate fix or an FX fixing). The attribute names have been adjusted from FpML to address the fact that the information is not limited to rates.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_observable_asset'})

    sourceProvider: InformationProviderEnum = Field(default=..., description="""An information source for obtaining a market data point. For example Bloomberg, Reuters, Telerate, etc.""", json_schema_extra = { "linkml_meta": {'annotations': {'rosetta_metadata': {'tag': 'rosetta_metadata',
                                              'value': 'scheme'}},
         'domain_of': ['InformationSource']} })
    sourcePage: Optional[str] = Field(default=None, description="""A specific page for the source for obtaining a market data point. In FpML, this is specified as a scheme, rateSourcePageScheme, for which no coding Scheme or URI is specified.""", json_schema_extra = { "linkml_meta": {'annotations': {'rosetta_metadata': {'tag': 'rosetta_metadata',
                                              'value': 'scheme'}},
         'domain_of': ['InformationSource']} })
    sourcePageHeading: Optional[str] = Field(default=None, description="""The heading for the source on a given source page.""", json_schema_extra = { "linkml_meta": {'domain_of': ['InformationSource']} })


