    businessDays: Optional[int] = Field(default=None, description="""A number of business days. Its precise meaning is dependant on the context in which this element is used. ISDA 2003 Term: Business Day.""", json_schema_extra = { "linkml_meta": {'domain_of': ['SingleValuationDate', 'PhysicalSettlementPeriod']} })


