class CalculationPeriod(CalculationPeriodBase):
    """
    A data defining: the parameters used in the calculation of a fixed or floating rate calculation period amount. This data forms: part of cashflows representation of a swap stream.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'all_of': [{'description': 'NotionalChoice: condition to represent an FpML '
                                    'choice construct.',
                     'exactly_one_of': [{'slot_conditions': {'notionalAmount': {'name': 'notionalAmount',
                                                                                'value_presence': 'PRESENT'}}},
                                        {'slot_conditions': {'fxLinkedNotionalAmount': {'name': 'fxLinkedNotionalAmount',
                                                                                        'value_presence': 'PRESENT'}}}]},
                    {'description': 'RateChoice: condition to represent an FpML choice '
                                    'construct.',
                     'exactly_one_of': [{'slot_conditions': {'floatingRateDefinition': {'name': 'floatingRateDefinition',
                                                                                        'value_presence': 'PRESENT'}}},
                                        {'slot_conditions': {'fixedRate': {'name': 'fixedRate',
                                                                           'value_presence': 'PRESENT'}}}]},
                    {'description': 'StartDateChoice: FpML validation rule ird-30 - '
                                    'Context: CalculationPeriod (complex type). '
                                    'unadjustedStartDate exists or adjustedStartDate '
                                    'exists.',
                     'exactly_one_of': [{'slot_conditions': {'adjustedStartDate': {'name': 'adjustedStartDate',
                                                                                   'value_presence': 'PRESENT'}}},
                                        {'slot_conditions': {'unadjustedStartDate': {'name': 'unadjustedStartDate',
                                                                                     'value_presence': 'PRESENT'}}}]},
                    {'description': 'EndDateChoice: FpML validation rule ird-31 - '
                                    'Context: CalculationPeriod (complex type). '
                                    'unadjustedEndDate exists or adjustedEndDate '
                                    'exists.',
                     'exactly_one_of': [{'slot_conditions': {'adjustedEndDate': {'name': 'adjustedEndDate',
                                                                                 'value_presence': 'PRESENT'}}},
                                        {'slot_conditions': {'unadjustedEndDate': {'name': 'unadjustedEndDate',
                                                                                   'value_presence': 'PRESENT'}}}]}],
         'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_product_common_schedule'})

    unadjustedStartDate: Optional[date] = Field(default=None, description="""The calculation start date, unadjusted.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriod']} })
    unadjustedEndDate: Optional[date] = Field(default=None, description="""The calculation end date, unadjusted.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriod']} })
    calculationPeriodNumberOfDays: Optional[int] = Field(default=None, description="""The number of days from the adjusted effective / start date to the adjusted termination / end date calculated in accordance with the applicable day count fraction.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriod', 'FutureValueAmount']} })
    notionalAmount: Optional[Decimal] = Field(default=None, description="""The amount that a cashflow will accrue interest on.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriod', 'FxLinkedNotionalAmount']} })
    fxLinkedNotionalAmount: Optional[FxLinkedNotionalAmount] = Field(default=None, description="""The amount that a cashflow will accrue interest on. This is the calculated amount of the FX linked - i.e. the other currency notional amount multiplied by the appropriate FX spot rate.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriod']} })
    floatingRateDefinition: Optional[FloatingRateDefinition] = Field(default=None, description="""The floating rate reset information for the calculation period.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriod']} })
    fixedRate: Optional[Decimal] = Field(default=None, description="""The calculation period fixed rate. A per annum rate, expressed as a decimal. A fixed rate of 5% would be represented as 0.05.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriod',
                       'FixedAmountCalculationDetails',
                       'CollateralInterestCalculationParameters']} })
    dayCountYearFraction: Optional[Decimal] = Field(default=None, description="""The year fraction value of the calculation period, result of applying the ISDA rules for day count fraction defined in the ISDA Annex.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriod']} })
    forecastAmount: Optional[Money] = Field(default=None, description="""The amount representing the forecast of the accrued value of the calculation period. An intermediate value used to generate the forecastPaymentAmount in the PaymentCalculationPeriod.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriod']} })
    forecastRate: Optional[Decimal] = Field(default=None, description="""A value representing the forecast rate used to calculate the forecast future value of the accrual period. This is a calculated rate determined based on averaging the rates in the rateObservation elements, and incorporates all of the rate treatment and averaging rules. A value of 1% should be represented as 0.01.""", json_schema_extra = { "linkml_meta": {'domain_of': ['RateObservation', 'CalculationPeriod']} })
    adjustedStartDate: Optional[date] = Field(default=None, description="""The calculation period start date, adjusted according to any relevant business day convention.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriodBase']} })
    adjustedEndDate: Optional[date] = Field(default=None, description="""The calculation period end date, adjusted according to any relevant business day convention.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriodBase']} })


