class CalculationPeriodDates(ConfiguredBaseModel):
    """
    A data for: defining the parameters used to generate the calculation period dates schedule, including the specification of any initial or final stub calculation periods. A calculation period schedule consists of an optional initial stub calculation period, one or more regular calculation periods and an optional final stub calculation period. In the absence of any initial or final stub calculation periods, the regular part of the calculation period schedule is assumed to be between the effective date and the termination date. No implicit stubs are allowed, i.e. stubs must be explicitly specified using an appropriate combination of firstPeriodStartDate, firstRegularPeriodStartDate and lastRegularPeriodEndDate.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'annotations': {'rosetta_metadata': {'tag': 'rosetta_metadata',
                                              'value': 'key'}},
         'comments': ['Rosetta condition FpML_ird_16 is not stated in LinkML: if '
                      'firstRegularPeriodStartDate exists then terminationDate -> '
                      'adjustableDate -> unadjustedDate > firstRegularPeriodStartDate',
                      'Rosetta condition FpML_ird_17 is not stated in LinkML: if '
                      'lastRegularPeriodEndDate exists then terminationDate -> '
                      'adjustableDate -> unadjustedDate > lastRegularPeriodEndDate',
                      'Rosetta condition FpML_ird_18 is not stated in LinkML: if '
                      'firstRegularPeriodStartDate exists and lastRegularPeriodEndDate '
                      'exists then lastRegularPeriodEndDate > '
                      'firstRegularPeriodStartDate',
                      'Rosetta condition FpML_ird_20 is not stated in LinkML: if '
                      'lastRegularPeriodEndDate exists then lastRegularPeriodEndDate > '
                      'effectiveDate -> adjustableDate -> unadjustedDate',
                      'Rosetta condition FpML_ird_21 is not stated in LinkML: if '
                      'firstPeriodStartDate exists and effectiveDate exists then '
                      'firstPeriodStartDate -> adjustableDate -> unadjustedDate < '
                      'effectiveDate -> adjustableDate -> unadjustedDate',
                      'Rosetta condition FpML_ird_22 is not stated in LinkML: if '
                      'firstPeriodStartDate exists and firstRegularPeriodStartDate '
                      'exists then firstPeriodStartDate -> adjustableDate -> '
                      'unadjustedDate < firstRegularPeriodStartDate'],
         'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_product_common_schedule'})

    effectiveDate: Optional[AdjustableOrRelativeDate] = Field(default=None, description="""The first day of the terms of the trade. This day may be subject to adjustment in accordance with a business day convention.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CodeValue',
                       'AgreementEventInstruction',
                       'ClosedState',
                       'CounterpartyPositionBusinessEvent',
                       'IndexTransitionInstruction',
                       'StockSplitInstruction',
                       'PriceQuantity',
                       'FallbackRateParameters',
                       'CalculationPeriodDates',
                       'LegalAgreementBase',
                       'EventInstruction',
                       'MinimumTransferAmountAmendment',
                       'TerminationCurrencyAmendment',
                       'CancelableProvision',
                       'EconomicTerms']} })
    terminationDate: Optional[AdjustableOrRelativeDate] = Field(default=None, description="""The last day of the terms of the trade. This date may be subject to adjustments in accordance with the business day convention. It can also be specified in relation to another scheduled date (e.g. the last payment date).""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriodDates', 'EconomicTerms']} })
    calculationPeriodDatesAdjustments: Optional[BusinessDayAdjustments] = Field(default=None, description="""The specification of the business day convention and financial business centers used for adjusting any calculation period date if it would otherwise fall on a day that is not a business day in the specified business center.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriodDates']} })
    firstPeriodStartDate: Optional[AdjustableOrRelativeDate] = Field(default=None, description="""The start date of the calculation period. FpML specifies that for interest rate swaps this date must only be specified if it is not equal to the effective date. It is always specified in the case of equity swaps and credit default swaps with periodic payments. This date may be subject to adjustment in accordance with a business day convention.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriodDates']} })
    firstRegularPeriodStartDate: Optional[date] = Field(default=None, description="""The start date of the regular part of the calculation period schedule. It must only be specified if there is an initial stub calculation period. This day may be subject to adjustment in accordance with any adjustments specified in calculationPeriodDatesAdjustments.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriodDates']} })
    firstCompoundingPeriodEndDate: Optional[date] = Field(default=None, description="""The end date of the initial compounding period when compounding is applicable. It must only be specified when the compoundingMethod element is present and not equal to a value of None. This date may be subject to adjustment in accordance with any adjustments specified in calculationPeriodDatesAdjustments.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriodDates']} })
    lastRegularPeriodEndDate: Optional[date] = Field(default=None, description="""The end date of the regular part of the calculation period schedule. It must only be specified if there is a final stub calculation period. This day may be subject to adjustment in accordance with any adjustments specified in calculationPeriodDatesAdjustments.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriodDates']} })
    stubPeriodType: Optional[list[StubPeriodTypeEnum]] = Field(default=None, description="""Method to allocate any irregular period remaining after regular periods have been allocated between the effective and termination date. The multiplicity of 2 allows the possibility of expressing the type for both an initial and final stub at the same time.""", max_length=2, json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriodDates']} })
    calculationPeriodFrequency: Optional[CalculationPeriodFrequency] = Field(default=None, description="""The frequency at which calculation period end dates occur with the regular part of the calculation period schedule and their roll date convention.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CalculationPeriodDates']} })


