    positions: Optional[list[Position]] = Field(default=None, description="""The list of positions, each containing a Quantity and a Product.""", json_schema_extra = { "linkml_meta": {'domain_of': ['PortfolioState']} })
    lineage: Lineage = Field(default=..., description="""Pointer to the previous PortfolioState and new Event(s) leading to the current (new) state. Previous PortfolioState in the Lineage can be Null in case this is the start of the chain of Events.""", json_schema_extra = { "linkml_meta": {'domain_of': ['PortfolioState']} })


