class LimitApplicableExtended(LimitApplicable):
    """
    A class to represent the CDM attributes that are not part of the FpML standard. Once broader usage is confirmed, it is expected that those two classes can be collapsed.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'all_of': [{'description': 'From LimitApplicable. LimitApplicableChoice: '
                                    'Choice rule to represent an FpML choice '
                                    'construct.',
                     'exactly_one_of': [{'slot_conditions': {'amountUtilized': {'name': 'amountUtilized',
                                                                                'value_presence': 'PRESENT'}}},
                                        {'slot_conditions': {'utilization': {'name': 'utilization',
                                                                             'value_presence': 'PRESENT'}}},
                                        {'all_of': [{'slot_conditions': {'amountUtilized': {'name': 'amountUtilized',
                                                                                            'value_presence': 'ABSENT'}}},
                                                    {'slot_conditions': {'utilization': {'name': 'utilization',
                                                                                         'value_presence': 'ABSENT'}}}]}]}],
         'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_event_workflow'})

    limitLevel: Optional[LimitLevelEnum] = Field(default=None, description="""The level at which the limit is set: customer business, proprietary business or account level. This attribute is specified as a string as part of the CME clearing confirmation specification.""", json_schema_extra = { "linkml_meta": {'annotations': {'rosetta_metadata': {'tag': 'rosetta_metadata',
                                              'value': 'scheme'}},
         'domain_of': ['LimitApplicableExtended']} })
    limitAmount: Optional[Decimal] = Field(default=None, description="""The total limit available for the limit level and limit type. While the attribute is of type integer in the CME schema, it has been specified to be of type number in the CDM to take into consideration java size limits as well as for consistency purposes with the way most monetary amounts are expressed.""", json_schema_extra = { "linkml_meta": {'domain_of': ['LimitApplicableExtended']} })
    limitImpactDueToTrade: Optional[Decimal] = Field(default=None, description="""The limit utilized by this specific trade. While the attribute is of type integer in the CME schema, it has been specified to be of type number in the CDM to take into consideration java size limits as well as for consistency purposes with the way most monetary amounts are expressed.""", json_schema_extra = { "linkml_meta": {'domain_of': ['LimitApplicableExtended']} })
    limitType: Optional[CreditLimitTypeEnum] = Field(default=None, description="""Standard code to indicate which type of credit line is being referred to - i.e. IM, DV01, PV01, CS01, Notional, Clip Size, Notional, maximumOrderQuantity.""", json_schema_extra = { "linkml_meta": {'annotations': {'rosetta_metadata': {'tag': 'rosetta_metadata',
                                              'value': 'scheme'}},
         'domain_of': ['LimitApplicable']} })
    clipSize: Optional[int] = Field(default=None, description="""This element is required in FpML, optional in CDM for the purpose of accommodating the CME data representation while making reference to the FpML one.""", json_schema_extra = { "linkml_meta": {'domain_of': ['LimitApplicable']} })
    amountUtilized: Optional[Decimal] = Field(default=None, description="""The limit utilised by all the cleared trades for the limit level and limit type. While the attribute is of type integer in FpML and the CME schema, it has been specified to be of type number in the CDM to take into consideration java size limits as well as for consistency purposes with the way most monetary amounts are expressed.""", json_schema_extra = { "linkml_meta": {'domain_of': ['LimitApplicable']} })
    utilization: Optional[CreditLimitUtilisation] = Field(default=None, json_schema_extra = { "linkml_meta": {'domain_of': ['LimitApplicable']} })
    amountRemaining: Optional[Decimal] = Field(default=None, description="""The limit remaining for the limit level and limit type. This does not take into account any pending trades. While the attribute is of type integer in FpML and the CME schema, it has been specified to be of type number in the CDM to take into consideration java size limits as well as for consistency purposes with the way most monetary amounts are expressed.""", json_schema_extra = { "linkml_meta": {'domain_of': ['LimitApplicable']} })
    currency: Optional[str] = Field(default=None, description="""The currency in which the applicable limit is denominated. The list of valid currencies is not presently positioned as an enumeration as part of the CDM because that scope is limited to the values specified by ISDA and FpML. As a result, implementers have to make reference to the relevant standard, such as the ISO 4217 standard for currency codes.""", json_schema_extra = { "linkml_meta": {'annotations': {'rosetta_metadata': {'tag': 'rosetta_metadata',
                                              'value': 'scheme'}},
         'domain_of': ['UnitType',
                       'CommodityReferenceFramework',
                       'NotDomesticCurrency',
                       'SpecifiedCurrency',
                       'FloatingRateIndexIdentification',
                       'AmountScheduleWithInitialValue',
                       'LimitApplicable',
                       'CalculationCurrencyElection',
                       'CollateralRounding',
                       'LegacyIndependentAmountRatingsBased',
                       'MinimumTransferAmountRatingsBased',
                       'TerminationCurrencyElection',
                       'ThresholdRatingsBased',
                       'FeaturePayment',
                       'DividendCurrency',
                       'FutureValueAmount',
                       'CollateralInterestParameters',
                       'ComputedAmount']} })
    velocity: Optional[Velocity] = Field(default=None, json_schema_extra = { "linkml_meta": {'domain_of': ['LimitApplicable']} })


