    floatingRateMultiplier: Optional[Decimal] = Field(default=None, description="""A rate multiplier to apply to the floating rate. The multiplier can be a positive or negative decimal. This element should only be included if the multiplier is not equal to 1 (one).""", json_schema_extra = { "linkml_meta": {'domain_of': ['FloatingRateDefinition']} })
    spread: Optional[Decimal] = Field(default=None, description="""The ISDA Spread, if any, which applies for the calculation period. The spread is a per annum rate, expressed as a decimal. For purposes of determining a calculation period amount, if positive the spread will be added to the floating rate and if negative the spread will be subtracted from the floating rate. A positive 10 basis point (0.1%) spread would be represented as 0.001.""", json_schema_extra = { "linkml_meta": {'domain_of': ['SwapCurveValuation',
                       'FloatingRateDefinition',
                       'FloatingRateProcessingParameters',
                       'CommodityPriceReturnTerms']} })
    capRate: Optional[list[Strike]] = Field(default=None, description="""The cap rate, if any, which applies to the floating rate for the calculation period. The cap rate (strike) is only required where the floating rate on a swap stream is capped at a certain strike level. The cap rate is assumed to be exclusive of any spread and is a per annum rate, expressed as a decimal. A cap rate of 5% would be represented as 0.05.""", json_schema_extra = { "linkml_meta": {'domain_of': ['FloatingRateDefinition', 'FloatingRateProcessingParameters']} })
    floorRate: Optional[list[Strike]] = Field(default=None, description="""The floor rate, if any, which applies to the floating rate for the calculation period. The floor rate (strike) is only required where the floating rate on a swap stream is floored at a certain strike level. The floor rate is assumed to be exclusive of any spread and is a per annum rate, expressed as a decimal. The floor rate of 5% would be represented as 0.05.""", json_schema_extra = { "linkml_meta": {'domain_of': ['FloatingRateDefinition', 'FloatingRateProcessingParameters']} })


