    obligations: Optional[Obligations] = Field(default=None, description="""The underlying obligations of the reference entity on which you are buying or selling protection. The credit events Failure to Pay, Obligation Acceleration, Obligation Default, Restructuring, Repudiation/Moratorium are defined with respect to these obligations.""", json_schema_extra = { "linkml_meta": {'domain_of': ['SecurityInterestForObligations', 'ProtectionTerms']} })
    floatingAmountEvents: Optional[FloatingAmountEvents] = Field(default=None, description="""This element contains the ISDA terms relating to the floating rate payment events and the implied additional fixed payments, applicable to the credit derivatives transactions on mortgage-backed securities with pay-as-you-go or physical settlement.""", json_schema_extra = { "linkml_meta": {'domain_of': ['ProtectionTerms']} })


