class StubFloatingRate(ConfiguredBaseModel):
    """
    A class defining a floating rate.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_product_asset'})

    floatingRateIndex: FloatingRateIndexEnum = Field(default=..., description="""The floating rate index.""", json_schema_extra = { "linkml_meta": {'domain_of': ['AssetFloatingRateIndex',
                       'SwapCurveValuation',
                       'FallbackRateParameters',
                       'FloatingRateIndexIdentification',
                       'CollectFloatingRateOptionInstruction',
                       'ResetInstructionState',
                       'StubFloatingRate']} })
    indexTenor: Optional[Period] = Field(default=None, description="""The ISDA Designated Maturity, i.e. the tenor of the floating rate.""", json_schema_extra = { "linkml_meta": {'domain_of': ['AssetFloatingRateIndex',
                       'InflationIndex',
                       'SwapCurveValuation',
                       'StubFloatingRate']} })
    floatingRateMultiplierSchedule: Optional[ScheduleWithInitialValue] = Field(default=None, description="""A rate multiplier or multiplier schedule to apply to the floating rate. A multiplier schedule is expressed as explicit multipliers and dates. In the case of a schedule, the step dates may be subject to adjustment in accordance with any adjustments specified in the calculationPeriodDatesAdjustments. The multiplier can be a positive or negative decimal. This element should only be included if the multiplier is not equal to 1 (one) for the term of the stream.""", json_schema_extra = { "linkml_meta": {'domain_of': ['FloatingRate', 'StubFloatingRate']} })
    spreadSchedule: Optional[list[SpreadSchedule]] = Field(default=None, description="""The ISDA Spread or a Spread schedule expressed as explicit spreads and dates. In the case of a schedule, the step dates may be subject to adjustment in accordance with any adjustments specified in calculationPeriodDatesAdjustments. The spread is a per annum rate, expressed as a decimal. For purposes of determining a calculation period amount, if positive the spread will be added to the floating rate and if negative the spread will be subtracted from the floating rate. A positive 10 basis point (0.1%) spread would be represented as 0.001.""", json_schema_extra = { "linkml_meta": {'domain_of': ['FloatingRateBase', 'StubFloatingRate']} })
    rateTreatment: Optional[RateTreatmentEnum] = Field(default=None, description="""The specification of any rate conversion which needs to be applied to the observed rate before being used in any calculations. The two common conversions are for securities quoted on a bank discount basis which will need to be converted to either a Money Market Yield or Bond Equivalent Yield. See the Annex to the 2000 ISDA Definitions, Section 7.3. Certain General Definitions Relating to Floating Rate Options, paragraphs (g) and (h) for definitions of these terms.""", json_schema_extra = { "linkml_meta": {'domain_of': ['FloatingRate', 'StubFloatingRate']} })
    capRateSchedule: Optional[list[StrikeSchedule]] = Field(default=None, description="""The cap rate or cap rate schedule, if any, which applies to the floating rate. The cap rate (strike) is only required where the floating rate on a swap stream is capped at a certain level. A cap rate schedule is expressed as explicit cap rates and dates and the step dates may be subject to adjustment in accordance with any adjustments specified in calculationPeriodDatesAdjustments. The cap rate is assumed to be exclusive of any spread and is a per annum rate, expressed as a decimal. A cap rate of 5% would be represented as 0.05.""", json_schema_extra = { "linkml_meta": {'domain_of': ['FloatingRateBase', 'StubFloatingRate']} })
    floorRateSchedule: Optional[list[StrikeSchedule]] = Field(default=None, description="""The floor rate or floor rate schedule, if any, which applies to the floating rate. The floor rate (strike) is only required where the floating rate on a swap stream is floored at a certain strike level. A floor rate schedule is expressed as explicit floor rates and dates and the step dates may be subject to adjustment in accordance with any adjustments specified in calculationPeriodDatesAdjustments. The floor rate is assumed to be exclusive of any spread and is a per annum rate, expressed as a decimal. A floor rate of 5% would be represented as 0.05.""", json_schema_extra = { "linkml_meta": {'domain_of': ['FloatingRateBase', 'StubFloatingRate']} })


class StubValue(ConfiguredBaseModel):
    """
    A type defining how a stub calculation period amount is calculated. A single floating rate tenor different to that used for the regular part of the calculation periods schedule may be specified, or two floating rate tenors many be specified. If two floating rate tenors are specified then Linear Interpolation (in accordance with the 2000 ISDA Definitions, Section 8.3 Interpolation) is assumed to apply. Alternatively, an actual known stub rate or stub amount may be specified.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'all_of': [{'description': 'Unnamed condition (one-of)',
                     'exactly_one_of': [{'slot_conditions': {'floatingRate': {'name': 'floatingRate',
                                                                              'value_presence': 'PRESENT'}}},
                                        {'slot_conditions': {'stubRate': {'name': 'stubRate',
                                                                          'value_presence': 'PRESENT'}}},
                                        {'slot_conditions': {'stubAmount': {'name': 'stubAmount',
                                                                            'value_presence': 'PRESENT'}}}]}],
         'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_product_asset'})

    floatingRate: Optional[list[StubFloatingRate]] = Field(default=None, description="""The rates to be applied to the initial or final stub may be the linear interpolation of two different rates. While the majority of the time, the rate indices will be the same as that specified in the stream and only the tenor itself will be different, it is possible to specift two different rates. For example, a 2 month stub period may use the linear interpolation of a 1 month and 3 month rate. The different rates would be specified in this component. Note that a maximum of two rates can be specified. If a stub period uses the same floating rate index, including tenor, as the regular calculation periods then this should not be specified again within this component, i.e. the stub calculation period amount component may not need to be specified even if there is an initial or final stub period. If a stub period uses a different floating rate index compared to the regular calculation periods then this should be specified within this component. If specified here, they are likely to have id attributes, allowing them to be referenced from within the cashflows component.""", max_length=2, json_schema_extra = { "linkml_meta": {'domain_of': ['StubValue',
                       'FloatingAmountCalculationDetails',
                       'FloatingRateSettingDetails',
                       'CollateralInterestCalculationParameters']} })
    stubRate: Optional[Decimal] = Field(default=None, description="""An actual rate to apply for the initial or final stub period may have been agreed between the principal parties (in a similar way to how an initial rate may have been agreed for the first regular period). If an actual stub rate has been agreed then it would be included in this component. It will be a per annum rate, expressed as a decimal. A stub rate of 5% would be represented as 0.05.""", json_schema_extra = { "linkml_meta": {'domain_of': ['StubValue']} })
    stubAmount: Optional[Money] = Field(default=None, description="""An actual amount to apply for the initial or final stub period may have been agreed between the two parties. If an actual stub amount has been agreed then it would be included in this component.""", json_schema_extra = { "linkml_meta": {'domain_of': ['StubValue']} })


class Tranche(ConfiguredBaseModel):
    """
    The class to represent a CDS Tranche.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'all_of': [{'description': 'AttachmentPoint: FpML definition associated with '
                                    'the attachmentPoint element specifies that a '
                                    'schema facet to constraint the value between 0 to '
                                    '1 will be introduced in FpML 4.3.',
                     'slot_conditions': {'attachmentPoint': {'maximum_value': 1,
                                                             'minimum_value': 0,
                                                             'name': 'attachmentPoint'}}},
                    {'description': 'ExhaustionPoint: FpML definition associated with '
                                    'the exhaustionPoint element specifies that a '
                                    'schema facet to constraint the value between 0 to '
                                    '1 will be introduced in FpML 4.3.',
                     'slot_conditions': {'exhaustionPoint': {'maximum_value': 1,
                                                             'minimum_value': 0,
                                                             'name': 'exhaustionPoint'}}}],
         'comments': ['Rosetta condition AttachmentPointLessThanExhaustionPoint is not '
                      'stated in LinkML: attachmentPoint <= exhaustionPoint'],
         'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_product_asset'})

    attachmentPoint: Decimal = Field(default=..., description="""Lower bound percentage of the loss that the Tranche can endure, expressed as a decimal. An attachment point of 5% would be represented as 0.05. The difference between Attachment and Exhaustion points is called the width of the Tranche.""", json_schema_extra = { "linkml_meta": {'domain_of': ['Tranche']} })
    exhaustionPoint: Decimal = Field(default=..., description="""Upper bound percentage of the loss that the Tranche can endure, expressed as a decimal. An exhaustion point of 5% would be represented as 0.05. The difference between Attachment and Exhaustion points is call the width of the Tranche.""", json_schema_extra = { "linkml_meta": {'domain_of': ['Tranche']} })
    incurredRecoveryApplicable: Optional[bool] = Field(default=None, description="""Outstanding Swap Notional Amount is defined at any time on any day, as the greater of: (a) Zero; If Incurred Recovery Amount Applicable: (b) The Original Swap Notional Amount minus the sum of all Incurred Loss Amounts and all Incurred Recovery Amounts (if any) determined under this Confirmation at or prior to such time.Incurred Recovery Amount not populated: (b) The Original Swap Notional Amount minus the sum of all Incurred Loss Amounts determined under this Confirmation at or prior to such time.""", json_schema_extra = { "linkml_meta": {'domain_of': ['Tranche']} })


