    volatilityCapFactor: Optional[Decimal] = Field(default=None, description="""Volatility Cap Amount in accordance with the ISDA 2011 Equity Derivatives Definitions. The Calculated VolCapAmt can be optionally provided.""", json_schema_extra = { "linkml_meta": {'domain_of': ['VolatilityCapFloor']} })


