class Collateral(ConfiguredBaseModel):
    """
    A type for defining the obligations of the counterparty subject to credit support requirements.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'all_of': [{'any_of': [{'slot_conditions': {'independentAmount': {'name': 'independentAmount',
                                                                           'value_presence': 'PRESENT'}}},
                                {'slot_conditions': {'collateralPortfolio': {'name': 'collateralPortfolio',
                                                                             'value_presence': 'PRESENT'}}}],
                     'description': 'CollateralExists: Collateral must represent '
                                    'either a simple independent amount or full '
                                    'collateral portfolio.'},
                    {'description': 'Collateralchoice',
                     'exactly_one_of': [{'slot_conditions': {'independentAmount': {'name': 'independentAmount',
                                                                                   'value_presence': 'PRESENT'}}},
                                        {'slot_conditions': {'portfolioIdentifier': {'name': 'portfolioIdentifier',
                                                                                     'value_presence': 'PRESENT'}}},
                                        {'slot_conditions': {'collateralPortfolio': {'name': 'collateralPortfolio',
                                                                                     'value_presence': 'PRESENT'}}},
                                        {'all_of': [{'slot_conditions': {'independentAmount': {'name': 'independentAmount',
                                                                                               'value_presence': 'ABSENT'}}},
                                                    {'slot_conditions': {'portfolioIdentifier': {'name': 'portfolioIdentifier',
                                                                                                 'value_presence': 'ABSENT'}}},
                                                    {'slot_conditions': {'collateralPortfolio': {'name': 'collateralPortfolio',
                                                                                                 'value_presence': 'ABSENT'}}}]}]}],
         'annotations': {'rosetta_metadata': {'tag': 'rosetta_metadata',
                                              'value': 'key'}},
         'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_product_collateral',
         'rules': [{'description': 'CollateralProvisions: When a collateral portfolio '
                                   'is provided, collateral provisions must exists '
                                   'that govern this collateral.',
                    'postconditions': {'slot_conditions': {'collateralProvisions': {'name': 'collateralProvisions',
                                                                                    'value_presence': 'PRESENT'}}},
                    'preconditions': {'slot_conditions': {'collateralPortfolio': {'name': 'collateralPortfolio',
                                                                                  'value_presence': 'PRESENT'}}}}]})

    independentAmount: Optional[IndependentAmount] = Field(default=None, description="""Independent Amount is an amount that usually less creditworthy counterparties are asked to provide. It can either be a fixed amount or a percentage of the Transaction's value. The Independent Amount can be: (i) transferred before any trading between the parties occurs (as a deposit at a third party's account or with the counterparty) or (ii) callable after trading has occurred (typically because a downgrade has occurred). In situation (i), the Independent Amount is not included in the calculation of Exposure, but in situation (ii), it is included in the calculation of Exposure. Thus, for situation (ii), the Independent Amount may be transferred along with any collateral call. Independent Amount is a defined term in the ISDA Credit Support Annex. ('with respect to a party, the amount specified as such for that party in Paragraph 13; if no amount is specified, zero').""", json_schema_extra = { "linkml_meta": {'domain_of': ['CreditSupportObligationsLegacy',
                       'CreditSupportObligationsVariationMargin',
                       'Collateral']} })
    portfolioIdentifier: Optional[list[Identifier]] = Field(default=None, description="""A list of identifiers pointing to the collateral portfolios which contain the collateral which covers a trade.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CollateralPortfolio', 'Collateral']} })
    collateralPortfolio: Optional[list[CollateralPortfolio]] = Field(default=None, description="""The collateral portfolios which contain the collateral which covers a trade. (NB: this can be provided by reference to a global key for each CollateralPortfolio object)""", json_schema_extra = { "linkml_meta": {'annotations': {'rosetta_metadata': {'tag': 'rosetta_metadata',
                                              'value': 'reference'}},
         'domain_of': ['MarginCallBase', 'Collateral']} })
    collateralProvisions: Optional[CollateralProvisions] = Field(default=None, description="""specifies the collateral provisions of the product.""", json_schema_extra = { "linkml_meta": {'domain_of': ['Collateral']} })


