    earliestCancellationTime: Optional[BusinessCenterTime] = Field(default=None, description="""The earliest time in a business day that notice of cancelation can be given.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CancelableProvision']} })
    latestCancelationTime: Optional[BusinessCenterTime] = Field(default=None, description="""The latest time at which notice of cancelation can be given.""", json_schema_extra = { "linkml_meta": {'domain_of': ['CancelableProvision']} })
