    product: NonTransferableProduct = Field(default=..., description="""The underlying product to be included in a contract or execution.""", json_schema_extra = { "linkml_meta": {'domain_of': ['ExecutionInstruction',
                       'TermsChangeInstruction',
                       'AggregationParameters',
                       'PositionBase',
                       'ExcludedProducts',
                       'TradableProduct']} })
    tradeLot: list[TradeLot] = Field(default=..., description="""Specifies the price, quantity and effective date of each trade lot, when the same product may be traded multiple times in different lots with the same counterparty. In a trade increase, a new trade lot is added to the list, with the corresponding effective date. In a trade decrease, the existing trade lot(s) are decreased of the corresponding quantity (and an unwind fee may have to be settled). The multiple cardinality and the ability to increase existing trades is used for Equity Swaps in particular.""", json_schema_extra = { "linkml_meta": {'domain_of': ['TradableProduct']} })
    counterparty: list[Counterparty] = Field(default=..., description="""Specifies the parties which are the two counterparties to the transaction. The product is agnostic to the actual parties to the transaction, with the party references abstracted away from the product definition and replaced by the counterparty enum (e.g. CounterpartyEnum values Party1 or Party2). The counterparty enum can then be positioned in the product (e.g. to specify which counterparty is the payer, receiver etc) and this counterparties attribute, which is positioned outside of the product definition, allows the counterparty enum to be associated with an actual party reference.""", min_length=2, max_length=2, json_schema_extra = { "linkml_meta": {'annotations': {'doc_reference': {'tag': 'doc_reference',
                                           'value': 'ICMA GMRA namingConvention '
                                                    'Party'}},
         'domain_of': ['ExecutionInstruction',
                       'PartyChangeInstruction',
                       'AgreementTerms',
                       'ClauseLibraryClause',
                       'ClauseLibraryClauseVariant',
                       'EligibleCollateralSpecification',
                       'TradableProduct']} })
    ancillaryParty: Optional[list[AncillaryParty]] = Field(default=None, description="""Specifies the parties with ancillary roles in the transaction. The product is agnostic to the actual parties involved in the transaction, with the party references abstracted away from the product definition and replaced by the AncillaryRoleEnum. The AncillaryRoleEnum can then be positioned in the product and this AncillaryParty type, which is positioned outside of the product definition, allows the AncillaryRoleEnum to be associated with an actual party reference.""", json_schema_extra = { "linkml_meta": {'domain_of': ['AncillaryEntity',
                       'ExecutionInstruction',
                       'PartyChangeInstruction',
                       'TermsChangeInstruction',
                       'TradableProduct']} })
    adjustment: Optional[NotionalAdjustmentEnum] = Field(default=None, description="""Specifies the conditions that govern the adjustment to the quantity of a product being traded: e.g. execution, portfolio rebalancing etc. It is typically used in the context of Equity Swaps.""", json_schema_extra = { "linkml_meta": {'domain_of': ['TermsChangeInstruction', 'TradableProduct']} })


