class TradeLot(ConfiguredBaseModel):
    """
    Specifies the price and quantity of a trade lot, where the same product could be traded multiple times with the same counterparty but in different lots (at a different date, in a different quantity and at a different price). One trade lot combined with a product definition specifies the entire economics of a trade. The lifecycle mechanics of each such trade lot (e.g. cashflow payments) is independent of the other lots.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_product_template'})

    lotIdentifier: Optional[list[Identifier]] = Field(default=None, description="""Specifies one or more identifiers for the lot, if any.""", json_schema_extra = { "linkml_meta": {'domain_of': ['ExecutionInstruction', 'QuantityChangeInstruction', 'TradeLot']} })
    priceQuantity: list[PriceQuantity] = Field(default=..., description="""Specifies the settlement characteristics of a trade lot: price, quantity, observable (optionally) and the settlement terms. This attribute has a multiple cardinality to allow to specify the price, quantity and observable of different legs in a single, composite product (e.g. a Swap).""", json_schema_extra = { "linkml_meta": {'domain_of': ['ExecutionInstruction',
                       'IndexTransitionInstruction',
                       'PositionBase',
                       'PayoutBase',
                       'TradeLot']} })


class TransferableProduct(ConfiguredBaseModel):
    """
    A TransferableProduct is a type of financial product which can be held or transferred, represented as an Asset with the addition of specific EconomicTerms.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'comments': ['Rosetta condition AssetPartyRoleExists is not stated in LinkML: '
                      'asset ->> partyRole exists'],
         'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_product_template'})

    asset: Asset = Field(default=..., description="""An Asset is defined as something that can be owned and transferred in the financial markets.""", json_schema_extra = { "linkml_meta": {'domain_of': ['TransferBase', 'PositionBase', 'TransferableProduct']} })
    economicTerms: EconomicTerms = Field(default=..., description="""The price forming features, including payouts and provisions.""", json_schema_extra = { "linkml_meta": {'domain_of': ['NonTransferableProduct', 'TransferableProduct']} })
    productPartyRole: CounterpartyRoleEnum = Field(default=..., description="""Overrides the parties on the trade to identify the party with the obligation to pay dividends or coupons, e.g issuer.""", json_schema_extra = { "linkml_meta": {'domain_of': ['TransferableProduct']} })


class Underlier(ConfiguredBaseModel):
    """
    The underlying financial product that will be physically or cash settled, which can be of any type, eg an asset such as cash or a security, a product, or the cash settlement of an index rate. Conditions are usually applied when used in a data type, such as a payout, to ensure this aligns with the use case.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'all_of': [{'description': 'OneOf: A choice type holds exactly one of its '
                                    'options.',
                     'exactly_one_of': [{'slot_conditions': {'Observable': {'name': 'Observable',
                                                                            'value_presence': 'PRESENT'}}},
                                        {'slot_conditions': {'Product': {'name': 'Product',
                                                                         'value_presence': 'PRESENT'}}}]}],
         'annotations': {'rosetta_choice': {'tag': 'rosetta_choice', 'value': 'true'}},
         'from_schema': 'https://w3id.org/lmodel/common-domain-model/cdm_product_template'})

    Observable: Optional[Observable] = Field(default=None, description="""Specifies the object to be observed for a price, it could be an asset or a reference.""", json_schema_extra = { "linkml_meta": {'annotations': {'rosetta_metadata': {'tag': 'rosetta_metadata',
                                              'value': 'address'}},
         'domain_of': ['Underlier']} })
    Product: Optional[Product] = Field(default=None, description="""Enables either a TransferableProduct or a NonTransferableProduct to be used in an underlier.""", json_schema_extra = { "linkml_meta": {'domain_of': ['Underlier']} })


